/**
 * Python-level exception mirrors.
 *
 * The original script lets a `ValueError` from `int()` escape `main()`, so the
 * interpreter prints a traceback and exits with status 1.  argparse instead
 * raises `SystemExit` (status 0 for --help, 2 for a usage error).  Modelling
 * both as real JS errors keeps the control flow of the entry point identical
 * to the Python one.
 */

export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = "ValueError";
  }
}

export class PySystemExit extends Error {
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.name = "SystemExit";
    this.code = code;
  }
}

