/**
 * Small pieces of CPython's `str` behaviour that the script depends on:
 * whitespace stripping (used by `int()`), code-point iteration (used by
 * `ord()`) and `repr()` (used in the `ValueError` message).
 */

// Code points for which CPython's Py_UNICODE_ISSPACE() is true.
const WHITESPACE = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20,
  0x85, 0xa0, 0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007,
  0x2008, 0x2009, 0x200a,
  0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

/** Iterate a string by code point, the way Python iterates a `str`. */
export function codePoints(text) {
  return Array.from(text, (ch) => ch.codePointAt(0));
}

export function isPythonSpace(codePoint) {
  return WHITESPACE.has(codePoint);
}

/** Equivalent of `text.strip()` with no argument. */
export function pyStrip(text) {
  const chars = Array.from(text);
  let start = 0;
  let end = chars.length;
  while (start < end && isPythonSpace(chars[start].codePointAt(0))) start += 1;
  while (end > start && isPythonSpace(chars[end - 1].codePointAt(0))) end -= 1;
  return chars.slice(start, end).join("");
}

/** Equivalent of `str.isprintable()` for a single character. */
function isPrintable(ch) {
  return ch === " " || !/[\p{C}\p{Z}]/u.test(ch);
}

function escapeCodePoint(codePoint) {
  if (codePoint < 0x100) return "\\x" + codePoint.toString(16).padStart(2, "0");
  if (codePoint < 0x10000) return "\\u" + codePoint.toString(16).padStart(4, "0");
  return "\\U" + codePoint.toString(16).padStart(8, "0");
}

/** Equivalent of `repr()` for a `str`. */
export function pyRepr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of text) {
    if (ch === "\\") out += "\\\\";
    else if (ch === quote) out += "\\" + quote;
    else if (ch === "\n") out += "\\n";
    else if (ch === "\r") out += "\\r";
    else if (ch === "\t") out += "\\t";
    else if (isPrintable(ch)) out += ch;
    else out += escapeCodePoint(ch.codePointAt(0));
  }
  return out + quote;
}

