/**
 * `int(text)` with base 10, as CPython implements it.
 *
 * The executable accepts everything CPython does, so the port has to as well:
 *
 *   int(' 7 ')  -> 7        surrounding whitespace is stripped
 *   int('+5')   -> 5        an explicit sign is allowed
 *   int('1_0')  -> 10       underscores may separate digits
 *   int('٣')    -> 3        any Unicode decimal digit counts
 *   int('9' * 41)           arbitrary precision -> BigInt, never Number
 *
 * Everything else raises ValueError with CPython's exact message.
 */

import { PyValueError } from "./errors.mjs";
import { pyRepr, pyStrip } from "./text.mjs";

const ND = /\p{Nd}/u;

/**
 * Numeric value of a Unicode decimal digit, or -1 if the character is not one.
 *
 * Digits that NFKC-fold onto ASCII (fullwidth, mathematical, ...) are resolved
 * that way.  The remaining decimal digit sets each occupy an isolated run of
 * ten code points, so counting the digits below the character gives its value.
 */
function digitValue(ch) {
  if (!ND.test(ch)) return -1;
  const folded = ch.normalize("NFKC");
  if (folded.length === 1 && folded >= "0" && folded <= "9") {
    return folded.codePointAt(0) - 0x30;
  }
  const codePoint = ch.codePointAt(0);
  let value = 0;
  while (value < 9 && ND.test(String.fromCodePoint(codePoint - value - 1))) {
    value += 1;
  }
  return value;
}

export function pyInt(text) {
  const invalid = () => {
    throw new PyValueError(
      `invalid literal for int() with base 10: ${pyRepr(text)}`,
    );
  };

  const chars = Array.from(pyStrip(text));
  let index = 0;
  let negative = false;
  if (chars[index] === "+" || chars[index] === "-") {
    negative = chars[index] === "-";
    index += 1;
  }

  let digits = "";
  let previousWasDigit = false;
  for (; index < chars.length; index += 1) {
    const ch = chars[index];
    if (ch === "_") {
      // An underscore is only legal between two digits.
      if (!previousWasDigit) invalid();
      previousWasDigit = false;
      continue;
    }
    const value = digitValue(ch);
    if (value < 0) invalid();
    digits += String(value);
    previousWasDigit = true;
  }
  if (!previousWasDigit) invalid();

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

