/**
 * `print()` and the `str()`/`repr()` spellings of the values it receives.
 *
 * The script prints a list of ints and a bool, so `[20, 22, 8, 12, 23, 28]`
 * and `True` have to come out byte for byte.
 */

import { pyRepr } from "./text.mjs";

/** `repr()` of a value, which is what a container uses for its items. */
export function pyReprValue(value) {
  if (typeof value === "bigint") return value.toString();
  if (typeof value === "boolean") return value ? "True" : "False";
  if (typeof value === "string") return pyRepr(value);
  if (Array.isArray(value)) return `[${value.map(pyReprValue).join(", ")}]`;
  if (value === null || value === undefined) return "None";
  return String(value);
}

/** `str()` of a value; differs from repr() only for strings. */
export function pyStr(value) {
  return typeof value === "string" ? value : pyReprValue(value);
}

/** `print(*values)`, writing straight to stdout so nothing is reformatted. */
export function pyPrint(...values) {
  process.stdout.write(values.map(pyStr).join(" ") + "\n");
}

