/**
 * The slice of `argparse.ArgumentParser` this CLI exercises: long options that
 * each take exactly one value, `-h/--help`, and no positionals.
 *
 * The behaviours below were read off the reference executable and are all
 * reproduced here:
 *
 *   --a x --a y            last occurrence wins
 *   --a=x                  '=' form
 *   --h                    unambiguous abbreviation of --help
 *   --a bc --b -1          '-1' looks like a negative number, so it is a value
 *   --a bc --b " -1"       a string containing a space is never an option
 *   --a bc --b             error: argument --b: expected one argument   (2)
 *   -a bc --b 1,2          error: the following arguments are required: --a (2)
 *   --a bc --b 1,2 extra   error: unrecognized arguments: extra         (2)
 *
 * Missing-required is reported before unrecognized-arguments, and both are
 * reported after any error raised while consuming an option's value.
 */

import { PySystemExit } from "./errors.mjs";
import { pyRepr } from "./text.mjs";

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

class Action {
  constructor(optionStrings, { dest, nargs, required, help, metavar }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs; // 0 for flags, 1 for options taking a value
    this.required = Boolean(required);
    this.help = help ?? null;
    this.metavar = metavar ?? null;
  }

  /** argparse's _get_action_name(): how the action is named in errors. */
  get name() {
    return this.optionStrings.join("/");
  }

  /** How the action appears in usage and in the options list. */
  formatInvocation() {
    if (this.nargs === 0) return this.optionStrings.join(", ");
    const metavar = this.metavar ?? this.dest.toUpperCase();
    return this.optionStrings.map((option) => `${option} ${metavar}`).join(", ");
  }

  formatUsage() {
    const metavar = this.metavar ?? this.dest.toUpperCase();
    const body =
      this.nargs === 0
        ? this.optionStrings[0]
        : `${this.optionStrings[0]} ${metavar}`;
    return this.required ? body : `[${body}]`;
  }
}

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    this.hasNegativeNumberOptionals = false;
    this.addArgument(["-h", "--help"], {
      nargs: 0,
      dest: "help",
      help: "show this help message and exit",
    });
  }

  addArgument(optionStrings, options = {}) {
    const dest =
      options.dest ?? optionStrings[optionStrings.length - 1].replace(/^-+/, "");
    const action = new Action(optionStrings, {
      dest,
      nargs: options.nargs ?? 1,
      required: options.required,
      help: options.help,
      metavar: options.metavar,
    });
    this.actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, action);
      if (NEGATIVE_NUMBER.test(optionString)) {
        this.hasNegativeNumberOptionals = true;
      }
    }
    return action;
  }

  // ---------------------------------------------------------------- messages

  formatUsage() {
    const parts = this.actions.map((action) => action.formatUsage());
    return `usage: ${this.prog} ${parts.join(" ")}\n`;
  }

  formatHelp() {
    const documented = this.actions.filter((action) => action.help !== null);
    // argparse indents entries by 2 and pads the invocation column to
    // min(longest + 2, 24) + 2 characters, then writes the help text.
    const longest = Math.max(
      ...this.actions.map((action) => action.formatInvocation().length + 2),
    );
    const helpPosition = Math.min(longest + 2, 24);
    const actionWidth = helpPosition - 4;

    let help = `${this.formatUsage()}\noptions:\n`;
    for (const action of this.actions) {
      const invocation = action.formatInvocation();
      if (!documented.includes(action) || action.help === null) {
        help += `  ${invocation}\n`;
      } else if (invocation.length <= actionWidth) {
        help += `  ${invocation.padEnd(actionWidth)}  ${action.help}\n`;
      } else {
        help += `  ${invocation}\n${" ".repeat(helpPosition)}${action.help}\n`;
      }
    }
    return help;
  }

  printHelp() {
    process.stdout.write(this.formatHelp());
  }

  exit(status = 0) {
    throw new PySystemExit(status);
  }

  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    this.exit(2);
  }

  // ----------------------------------------------------------------- parsing

  /**
   * argparse's _parse_optional(): null when the token is a positional,
   * otherwise [action|null, optionString, sep, explicitArg].
   */
  parseOptional(argString) {
    if (argString === "") return null;
    if (argString[0] !== "-") return null;
    if (this.optionStringActions.has(argString)) {
      return [this.optionStringActions.get(argString), argString, null, null];
    }
    if (argString.length === 1) return null;

    const equals = argString.indexOf("=");
    if (equals >= 0) {
      const optionString = argString.slice(0, equals);
      if (this.optionStringActions.has(optionString)) {
        return [
          this.optionStringActions.get(optionString),
          optionString,
          "=",
          argString.slice(equals + 1),
        ];
      }
    }

    const matches = this.getOptionTuples(argString);
    if (matches.length > 1) {
      const options = matches.map(([, optionString]) => optionString).join(", ");
      this.error(
        `ambiguous option: ${argString} could match ${options}`,
      );
    }
    if (matches.length === 1) return matches[0];

    if (NEGATIVE_NUMBER.test(argString) && !this.hasNegativeNumberOptionals) {
      return null;
    }
    if (argString.includes(" ")) return null;
    return [null, argString, null, null]; // an option this parser does not know
  }

  /** argparse's _get_option_tuples(): abbreviation matching. */
  getOptionTuples(argString) {
    const result = [];
    if (argString[1] === "-") {
      const equals = argString.indexOf("=");
      const prefix = equals >= 0 ? argString.slice(0, equals) : argString;
      const sep = equals >= 0 ? "=" : null;
      const explicitArg = equals >= 0 ? argString.slice(equals + 1) : null;
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(prefix)) {
          result.push([action, optionString, sep, explicitArg]);
        }
      }
    } else {
      const shortPrefix = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString === shortPrefix) {
          result.push([action, optionString, "", shortExplicitArg]);
        } else if (optionString.startsWith(argString)) {
          result.push([action, optionString, null, null]);
        }
      }
    }
    return result;
  }

  parseKnownArgs(argStrings) {
    const namespace = {};
    for (const action of this.actions) {
      if (action.nargs !== 0) namespace[action.dest] = null;
    }

    // Classify every token first: 'O' option, 'A' value, '-' the separator.
    // Everything after the first '--' is a value, whatever it looks like.
    const pattern = [];
    const optionTuples = [];
    let afterSeparator = false;
    for (const argString of argStrings) {
      if (afterSeparator) {
        pattern.push("A");
        optionTuples.push(null);
        continue;
      }
      if (argString === "--") {
        afterSeparator = true;
        pattern.push("-");
        optionTuples.push(null);
        continue;
      }
      const optionTuple = this.parseOptional(argString);
      pattern.push(optionTuple === null ? "A" : "O");
      optionTuples.push(optionTuple);
    }

    const extras = [];
    const seen = new Set();
    let index = 0;
    while (index < argStrings.length) {
      if (pattern[index] !== "O") {
        // No positionals are defined, so the token cannot be consumed.  The
        // separator itself ends up here too, exactly as argparse leaves it.
        extras.push(argStrings[index]);
        index += 1;
        continue;
      }

      const [action, , , explicitArg] = optionTuples[index];
      if (action === null) {
        extras.push(argStrings[index]);
        index += 1;
        continue;
      }
      seen.add(action);

      if (action.nargs === 0) {
        if (explicitArg !== null) {
          this.error(
            `argument ${action.name}: ignored explicit argument ${pyRepr(explicitArg)}`,
          );
        }
        if (action.dest === "help") {
          this.printHelp();
          this.exit(0);
        }
        index += 1;
        continue;
      }

      let value;
      if (explicitArg !== null) {
        value = explicitArg;
        index += 1;
      } else if (index + 1 < argStrings.length && pattern[index + 1] === "A") {
        value = argStrings[index + 1];
        index += 2;
      } else {
        this.error(`argument ${action.name}: expected one argument`);
      }
      namespace[action.dest] = value;
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.name);
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(", ")}`);
    }

    return [namespace, extras];
  }

  parseArgs(argStrings) {
    const [namespace, extras] = this.parseKnownArgs(argStrings);
    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(" ")}`);
    }
    return namespace;
  }
}

