/**
 * The traceback CPython prints when the `ValueError` from `int()` escapes
 * `main()`, followed by the line the PyInstaller bootloader adds.
 *
 * The line numbers and source text are those of the original test10.py, since
 * that is what the reference executable reports.
 */

const SCRIPT = "test10.py";
const FAILING_LINE = "    data = list(map(int, args.b.split(',')))";
const FAILING_EXPRESSION = "list(map(int, args.b.split(',')))";

export function formatTraceback(error) {
  const caretColumn = FAILING_LINE.indexOf(FAILING_EXPRESSION);
  return (
    [
      "Traceback (most recent call last):",
      `  File "${SCRIPT}", line 18, in <module>`,
      "    main()",
      `  File "${SCRIPT}", line 10, in main`,
      FAILING_LINE,
      " ".repeat(caretColumn) + "^".repeat(FAILING_EXPRESSION.length),
      `${error.name}: ${error.message}`,
      `[PYI-${process.pid}:ERROR] Failed to execute script 'test10' due to unhandled exception!`,
    ].join("\n") + "\n"
  );
}

export function printTraceback(error) {
  process.stderr.write(formatTraceback(error));
}

