/**
 * The BCH checksum core of bech32: the generator polynomial and the modulo
 * step every other routine is built on.
 *
 * Arithmetic runs on BigInt rather than Number because Python ints are
 * unbounded and the CLI happily accepts data values far beyond 32 bits
 * (`--b 1000000000000`, `--b -1`, `--b 9999...`).  JavaScript's `&`, `^`, `<<`
 * and `>>` on Number truncate to 32 bits and would diverge there, while on
 * BigInt they follow the same two's-complement-of-infinite-width rules Python
 * uses, including for negative values.
 */

const GENERATOR = [0x3b6a57b2n, 0x26508e6dn, 0x1ea119fan, 0x3d4233ddn, 0x2a1462b3n];

const LOW_25_BITS = 0x1ffffffn;

/** Internal function that computes the bech32 checksum. */
export function bech32Polymod(values) {
  let chk = 1n;
  for (const value of values) {
    const top = chk >> 25n;
    chk = ((chk & LOW_25_BITS) << 5n) ^ value;
    for (let i = 0n; i < 5n; i += 1n) {
      if ((top >> i) & 1n) chk ^= GENERATOR[Number(i)];
    }
  }
  return chk;
}

