/**
 * Checksum creation and verification, on top of the polymod step.
 *
 * The human-readable part is expanded by code point, matching Python's
 * `ord(x) for x in hrp`: a non-BMP character such as an emoji is one value
 * (U+1F600 -> 128512), not the two UTF-16 halves JavaScript stores it as.
 */

import { bech32Polymod } from "./polymod.mjs";

const CHECKSUM_LENGTH = 6;

/** Expand the HRP into values for checksum computation. */
export function bech32HrpExpand(hrp) {
  const values = Array.from(hrp, (ch) => BigInt(ch.codePointAt(0)));
  return [
    ...values.map((value) => value >> 5n),
    0n,
    ...values.map((value) => value & 31n),
  ];
}

/** Compute the checksum values given HRP and data. */
export function bech32CreateChecksum(hrp, data) {
  const values = [...bech32HrpExpand(hrp), ...data];
  const padding = Array(CHECKSUM_LENGTH).fill(0n);
  const polymod = bech32Polymod([...values, ...padding]) ^ 1n;
  const checksum = [];
  for (let i = 0; i < CHECKSUM_LENGTH; i += 1) {
    checksum.push((polymod >> (5n * BigInt(CHECKSUM_LENGTH - 1 - i))) & 31n);
  }
  return checksum;
}

/** Verify a checksum given HRP and converted data characters. */
export function bech32VerifyChecksum(hrp, data) {
  return bech32Polymod([...bech32HrpExpand(hrp), ...data]) === 1n;
}

