import * as bech32 from "./lib/bech32/index.mjs";
import { ArgumentParser } from "./lib/python/argparse.mjs";
import { PySystemExit, PyValueError } from "./lib/python/errors.mjs";
import { pyPrint } from "./lib/python/format.mjs";
import { pyInt } from "./lib/python/pyint.mjs";
import { printTraceback } from "./lib/python/traceback.mjs";

// argparse derives this from sys.argv[0]; the reference binary reports
// "test10_executable", so usage and error lines are emitted under that name.
const PROG = "test10_executable";

function main() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(["--a"], { required: true }); // HRP
  parser.addArgument(["--b"], { required: true }); // Data as comma-separated integers
  const args = parser.parseArgs(process.argv.slice(2));

  const data = args.b.split(",").map(pyInt);
  const checksum = bech32.bech32CreateChecksum(args.a, data); // Create checksum
  const combined = [...data, ...checksum];
  const isValid = bech32.bech32VerifyChecksum(args.a, combined); // Verify checksum
  pyPrint(checksum);
  pyPrint(isValid);
}

try {
  main();
} catch (error) {
  if (error instanceof PySystemExit) {
    process.exitCode = error.code;
  } else if (error instanceof PyValueError) {
    // Uncaught in the original script: traceback on stderr, exit status 1.
    printTraceback(error);
    process.exitCode = 1;
  } else {
    throw error;
  }
}

